lista de ƒ:
(nombre) => {
      if (typeof nombre !== "string") return null;
      let lista = diarsaba.get(nombre);
      if (!Array.isArray(lista) && diarsaba.get("sigilos lista #").includes(nombre.slice(-1))) {
          lista = [];
          diarsaba.set(nombre, lista);
          host.log("· <b>nace</b> «" + nombre + "», vacía");
